.darma-loader-darma-b13-accordion-squeeze { --accent: var(--loader-color, #b91c1c); --accent-2: var(--loader-secondary-color, #f8fafc); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .6); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b13-accordion-squeeze::before, .darma-loader-darma-b13-accordion-squeeze::after { content: ''; position: absolute; top: 0; width: 14%; height: 100%; border-radius: 4px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 32%, var(--accent))); }
.darma-loader-darma-b13-accordion-squeeze::before { left: 0; }
.darma-loader-darma-b13-accordion-squeeze::after { right: 0; }
.darma-loader-darma-b13-accordion-squeeze .darma-loader-darma-b13-accordion-squeeze__bellows { height: 82%; border-radius: 2px; background: repeating-linear-gradient(90deg, var(--accent-2) 0 8%, color-mix(in srgb, #000 28%, var(--accent-2)) 8% 16%); animation: darma-loader-darma-b13-accordion-squeeze-squeeze calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
@keyframes darma-loader-darma-b13-accordion-squeeze-squeeze { 0%, 100% { width: 76%; } 50% { width: 40%; } }

